const rights=`<section class="room-hero"><p>${sources.length}-source rights desk</p><h1>Evidence has conditions.</h1><blockquote>Publicly visible is not the same as reusable.</blockquote></section><section class="ledger"><div class="filters"><label>Search sources <input type="search" data-search placeholder="Institution, title, rights"></label><label>Disposition <select data-rights><option value="all">All dispositions</option>${[...new Set(sources.map(s=>s.disposition))].map(x=>`<option>${x}</option>`).join('')}</select></label><button type="button" data-reset>Reset</button><p data-count aria-live="polite">${sources.length} records</p></div><div data-grid>${sources.map(s=>`<article class="source" id="${s.id}" data-right="${s.disposition}" data-text="${(s.id+' '+s.title+' '+s.institution+' '+s.rights+' '+s.disposition).toLowerCase()}"><span>${s.id} · ${s.disposition}</span><h2>${esc(s.title)}</h2><p>${esc(s.institution)} · ${esc(s.date)}</p><p>${esc(s.rights)}</p><p>Retrieved ${s.retrieved}</p>${(sourceUse.get(s.id)||[]).length?`<p class="used-in">Used in ${sourceUse.get(s.id).map(id=>`<a href="/packages/${id.toLowerCase()}">${id}</a>`).join(', ')}</p>`:''}${s.url?`<a href="${s.url}">Canonical source ↗</a>`:`<p><b>Exact canonical record unresolved.</b> ${s.discoveryUrl?`<a href="${s.discoveryUrl}">Shared discovery portal ↗</a>`:''}</p>`}</article>`).join('')}</div></section>`;fs.writeFileSync(path.join(out,'rights.html'),shell('Rights desk',`A ${sources.length}-source point-of-claim rights ledger.`,rights,'rights'));
const evidence=`<section class="room-hero"><p>Object-level source protocol</p><h1>Evidence, not atmosphere.</h1><blockquote>Every object keeps its identifier, caption, rights, alt text, canonical source, file hash, and origin assessment.</blockquote></section><section class="provenance-note"><h2>Two media classes. No synthetic imagery.</h2><p><b>Archival collection images</b> are found online through official Met or Library of Congress records and reproduced only where the item-level record permits reuse. <b>Original editorial graphics</b> are deterministic typography and evidence compositions created by this publication system; they are labeled as graphics and never presented as documentary photographs.</p><p>“Not AI-generated” is established through that provenance chain and the reproducible local renderer—not a probabilistic detector.</p></section><section class="objects">${objectCards}</section><section><h2>Machine-readable manifests</h2><p><a class="enter" href="/evidence-assets.json" download>Download evidence-assets.json</a> · <a class="enter" href="/media-provenance.json" download>Download complete media-provenance.json</a></p></section>`;fs.writeFileSync(path.join(out,'evidence.html'),shell('Evidence',`${objects.length} rights-cleared public-collection objects with complete source and rights metadata.`,evidence,'evidence'));
